import sys
import requests
import json
import re

def main():
    if len(sys.argv) != 2:
        sys.stderr.write("Usage: fetch_template.py <URL>\n")
        sys.exit(1)

    url = sys.argv[1]
    try:
        response = requests.get(url)
        response.raise_for_status()
        data = response.json()
    except requests.RequestException as e:
        sys.stderr.write(f"Error fetching URL: {e}\n")
        sys.exit(1)
    except json.JSONDecodeError as e:
        sys.stderr.write(f"Error parsing JSON: {e}\n")
        sys.exit(1)

    template = sys.stdin.read()
    pattern = re.compile(r'\{\{\s*([^}]+)\s*\}\}')
    def replace_match(match):
        expr = match.group(1)
        try:
            return str(eval(expr, {'__builtins__': None}, {'data': data}))
        except Exception as e:
            sys.stderr.write(f"Error evaluating expression '{expr}': {e}\n")
            sys.exit(1)

    result = pattern.sub(replace_match, template)
    print(result)

if __name__ == "__main__":
    main()
